import React, { useState, useRef } from "react";
import { 
  X, User, Truck, AlertCircle, BookOpen, 
  Award, AlertTriangle, CheckCircle, Activity, MapPin
} from "lucide-react";
import ScheduleTab from "../tabs/ScheduleTab";
import ReportsTab from "../tabs/ReportsTab";
import TrainingTab from "../tabs/TrainingTab";

const WorkerDashboard = () => {
  const [activeTab, setActiveTab] = useState("schedule");
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [selectedReport, setSelectedReport] = useState(null); // State to hold the specific report
  const scrollRef = useRef(null);

  // Data mapping for specific reports linked to Schedule IDs
  const reportData = {
    'LOC_04': {
      id: 'REP-772',
      title: 'Waste Overflow',
      loc: 'Sector 4',
      description: 'The bin at the corner of 5th Ave is completely overflowing. Plastic bottles are everywhere on the sidewalk.',
      img: 'https://images.unsplash.com/photo-1605600611284-19561ad7ddf0?q=80&w=600',
    },
    'LOC_15': {
      id: 'REP-801',
      title: 'Illegal Dumping',
      loc: 'East Gate',
      description: 'Someone left old furniture and construction debris near the park entrance.',
      img: 'https://images.unsplash.com/photo-1530587191325-3db32d826c18?q=80&w=600',
    }
  };

  const handleOpenReport = (locationId) => {
    setSelectedReport(reportData[locationId]);
  };

  const tabs = [
    { id: "schedule", label: "Tasks", icon: <Truck size={24} />, color: "#CAD23C" },
    { id: "reports", label: "Issues", icon: <AlertCircle size={24} />, color: "#AB1717" },
    { id: "training", label: "Learn", icon: <BookOpen size={24} />, color: "#A1AED1" },
  ];

  const scrollToTab = (tabId) => {
    const index = tabs.findIndex(t => t.id === tabId);
    setActiveTab(tabId);
    scrollRef.current.scrollTo({ left: index * window.innerWidth, behavior: "smooth" });
  };

  const handleScroll = () => {
    if (scrollRef.current) {
      const index = Math.round(scrollRef.current.scrollLeft / window.innerWidth);
      if (tabs[index] && tabs[index].id !== activeTab) {
        setActiveTab(tabs[index].id);
      }
    }
  };

  return (
    <div className="h-screen bg-[#FDFAD8] font-sans relative overflow-hidden perspective-1000">

      {/* --- REPORT DETAIL MODAL --- */}
{selectedReport && (
  <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-[#47510B]/95 backdrop-blur-xl">
    {/* Fixed width 'max-w-sm' and fixed height 'h-[600px]' to prevent layout shifting */}
    <div className="bg-[#FDFAD8] w-full max-w-sm h-[600px] rounded-[50px] border-[8px] border-white overflow-hidden animate-slide-up flex flex-col shadow-2xl">

      {/* Header Image: Fixed height so it never squishes the content below */}
      <div className="h-44 min-h-[176px] w-full relative shrink-0">
        <img src={selectedReport.img} alt="Evidence" className="w-full h-full object-cover" />
        <button 
          onClick={() => setSelectedReport(null)}
          className="absolute top-4 right-4 w-10 h-10 bg-white rounded-full flex items-center justify-center text-[#AB1717] shadow-xl active:scale-90 transition-all"
        >
          <X size={20} strokeWidth={3} />
        </button>
        <div className="absolute bottom-4 left-4 bg-[#AB1717] text-white text-[9px] font-black px-3 py-1 rounded-full uppercase tracking-tighter">
          Evidence_File_{selectedReport.id.split('-')[1]}
        </div>
      </div>

      {/* Content Area: flex-1 and overflow-y-auto ensures this part scrolls if the text is long */}
      <div className="p-8 flex-1 overflow-y-auto no-scrollbar flex flex-col">
        <div className="flex justify-between items-start mb-6 shrink-0">
          <div>
            <h4 className="text-2xl font-black text-[#47510B] uppercase italic leading-tight">{selectedReport.title}</h4>
            <div className="flex items-center gap-2 mt-1 opacity-40">
              <MapPin size={12} />
              <span className="text-[10px] font-black uppercase tracking-widest">{selectedReport.loc}</span>
            </div>
          </div>
          <div className="text-right shrink-0">
            <p className="text-[8px] font-black opacity-30 uppercase">Submitted</p>
            <p className="text-[10px] font-black text-[#47510B]">{selectedReport.time}</p>
          </div>
        </div>

        <div className="space-y-4 mb-6">
          <div className="flex items-center gap-3 p-3 bg-white rounded-2xl border-2 border-[#47510B]/5 shrink-0">
            <User size={16} className="text-[#CAD23C]" />
            <p className="text-[10px] font-bold text-[#47510B]">Reported by: <span className="opacity-50">{selectedReport.citizen}</span></p>
          </div>

          {/* Description: Leading-relaxed and better padding for readability */}
          <div className="p-5 bg-white rounded-3xl border-2 border-[#47510B]/10 italic text-sm text-[#47510B]/80 leading-relaxed shadow-inner">
            "{selectedReport.description}"
          </div>
        </div>

        {/* Action Button: mt-auto pushes it to the bottom of the container */}
        <button 
          onClick={() => setSelectedReport(null)}
          className="mt-auto w-full py-5 shrink-0 bg-[#47510B] text-[#CAD23C] rounded-[25px] font-black uppercase text-sm shadow-xl flex items-center justify-center gap-3 active:scale-95 transition-all"
        >
          <CheckCircle size={18} /> Mark as Resolved
        </button>
      </div>
    </div>
  </div>
)}

      {/* --- PROFILE LAYER (READ-ONLY) --- */}
<div className={`absolute inset-0 z-[80] transition-all duration-1000 ease-[cubic-bezier(0.23,1,0.32,1)] flex items-center justify-center p-4 md:p-12 ${isProfileOpen ? "opacity-100 scale-100 translate-z-0" : "opacity-0 scale-125 translate-z-[-500px] pointer-events-none"}`}>
  <div className="w-full h-full bg-[#FDFAD8] rounded-[60px] shadow-2xl relative overflow-hidden flex flex-col border-[12px] border-white">

    {/* Close Button */}
    <button onClick={() => setIsProfileOpen(false)} className="absolute top-6 right-6 w-12 h-12 bg-white rounded-full flex items-center justify-center text-[#47510B] hover:rotate-90 transition-transform shadow-xl z-50 border-2 border-[#47510B]/5">
      <X size={24} />
    </button>

    <div className="flex-1 overflow-y-auto no-scrollbar p-8 md:p-16">

      {/* HEADER SECTION */}
      <div className="flex flex-col md:flex-row justify-between items-start gap-8 mb-12">
        <div>
          <h3 className="text-5xl font-black italic text-[#47510B] uppercase tracking-tighter leading-none mb-4">
            Marcus<br/><span className="text-[#CAD23C]">Sterling.</span>
          </h3>
          <div className="flex gap-2">
            <span className="px-3 py-1 bg-[#47510B] text-[#CAD23C] rounded-lg text-[9px] font-black uppercase tracking-widest">UNIT_7729</span>
            <span className="px-3 py-1 border-2 border-[#47510B] text-[#47510B] rounded-lg text-[9px] font-black uppercase tracking-widest">SECTOR_04</span>
          </div>
        </div>

        {/* COMPACT STATS */}
        <div className="flex gap-3">
          <div className="bg-[#CAD23C] px-6 py-4 rounded-[25px] border-2 border-[#47510B] text-center shadow-[4px_4px_0_0_#47510B]">
            <p className="text-[8px] font-black opacity-60 uppercase">Badges</p>
            <p className="text-xl font-black italic">12</p>
          </div>
          <div className="bg-[#AB1717] px-6 py-4 rounded-[25px] border-2 border-[#47510B] text-center text-white shadow-[4px_4px_0_0_#47510B]">
            <p className="text-[8px] font-black opacity-60 uppercase text-[#FDFAD8]">Strikes</p>
            <p className="text-xl font-black italic text-[#FDFAD8]">01</p>
          </div>
        </div>
      </div>

      {/* PERSONAL DETAILS (RESTORED) */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-12">
        <div className="p-5 bg-white rounded-[30px] border-2 border-[#47510B]/10">
          <p className="text-[9px] font-black text-[#A1AED1] uppercase mb-1 tracking-widest font-mono">Registry_Email</p>
          <p className="font-bold text-[#47510B] text-sm lowercase">m.sterling@trash2track.gov</p>
        </div>
        <div className="p-5 bg-white rounded-[30px] border-2 border-[#47510B]/10">
          <p className="text-[9px] font-black text-[#A1AED1] uppercase mb-1 tracking-widest font-mono">Comm_Line</p>
          <p className="font-bold text-[#47510B] text-sm">+44 7700 90001</p>
        </div>
        <div className="p-5 bg-white rounded-[30px] border-2 border-[#47510B]/10">
          <p className="text-[9px] font-black text-[#A1AED1] uppercase mb-1 tracking-widest font-mono">License_Class</p>
          <p className="font-bold text-[#47510B] text-sm uppercase">HGV / Heavy_Lift</p>
        </div>
      </div>

      {/* COMPACT HISTORY SECTION */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-10">

        {/* PICKUP LOGS */}
        <div>
          <h4 className="flex items-center gap-2 text-xl font-black italic text-[#47510B] uppercase tracking-tighter mb-4 px-2">
            <Truck size={18} /> Pickup_Archive
          </h4>
          <div className="max-h-[300px] overflow-y-auto pr-3 space-y-2 custom-scrollbar">
            {[1, 2, 3, 4, 5, 6].map((i) => (
              <div key={i} className={`p-4 rounded-[20px] border-2 border-[#47510B] flex items-center justify-between transition-all ${i <= 3 ? 'bg-white shadow-[4px_4px_0_0_#CAD23C] opacity-100' : 'bg-white/40 border-dashed opacity-50'}`}>
                <div className="flex items-center gap-3">
                  <div className="w-8 h-8 rounded-lg bg-[#FDFAD8] flex items-center justify-center">
                    <CheckCircle size={14} className="text-[#47510B]" />
                  </div>
                  <div>
                    <p className="text-[10px] font-black text-[#47510B] uppercase">Sector_0{i}_Node</p>
                    <p className="text-[8px] font-bold opacity-30 italic">MAR 1{i}_2026</p>
                  </div>
                </div>
                <span className="text-[8px] font-black bg-[#47510B] text-[#CAD23C] px-2 py-0.5 rounded uppercase">Verified</span>
              </div>
            ))}
          </div>
        </div>

        {/* REPORT LOGS */}
        <div>
          <h4 className="flex items-center gap-2 text-xl font-black italic text-[#47510B] uppercase tracking-tighter mb-4 px-2">
            <Activity size={18} /> Resolution_Logs
          </h4>
          <div className="max-h-[300px] overflow-y-auto pr-3 space-y-2 custom-scrollbar">
            {[1, 2, 3, 4, 5, 6].map((i) => (
              <div key={i} className={`p-4 rounded-[20px] border-2 border-[#47510B] flex items-center justify-between transition-all ${i <= 3 ? 'bg-white shadow-[4px_4px_0_0_#AB1717] opacity-100' : 'bg-white/40 border-dashed opacity-50'}`}>
                <div className="flex items-center gap-3">
                  <div className="w-8 h-8 rounded-lg bg-[#FDFAD8] flex items-center justify-center text-[#AB1717]">
                    <AlertCircle size={14} />
                  </div>
                  <div>
                    <p className="text-[10px] font-black text-[#47510B] uppercase">Issue_Fixed_0{i}</p>
                    <p className="text-[8px] font-bold opacity-30 italic">MAR 0{i}_2026</p>
                  </div>
                </div>
                <div className="w-2 h-2 rounded-full bg-[#CAD23C]" />
              </div>
            ))}
          </div>
        </div>

      </div>
    </div>
  </div>
</div>

      {/* --- DASHBOARD LAYER --- */}
<div className={`h-full w-full transition-all duration-1000 ease-[cubic-bezier(0.23,1,0.32,1)] flex flex-col ${isProfileOpen ? "scale-50 opacity-0 -translate-x-full pointer-events-none" : "scale-100 opacity-100"}`}>

  {/* FIXED HEADER SECTION */}
  <header className="absolute top-0 w-full left-0 pt-12 px-10 z-[70] flex justify-between items-center pointer-events-none">
    {/* Tab Name - Dynamic based on activeTab */}
    <h2 className="text-3xl font-black italic text-[#47510B] uppercase tracking-tighter pointer-events-auto">
      {activeTab === "schedule" ? "Todays Schedule" : activeTab}<span className="text-[#CAD23C]">.</span>
    </h2>

  {/* Profile Button */}
    <button 
      onClick={() => setIsProfileOpen(true)} 
      className="bg-[#47510B] p-1.5 pr-5 rounded-2xl flex items-center gap-3 border-2 border-white shadow-lg text-[#CAD23C] hover:scale-105 transition-all pointer-events-auto"
    >
      <div className="w-9 h-9 rounded-xl bg-[#CAD23C] flex items-center justify-center text-[#47510B]">
        <User size={20} strokeWidth={3} />
      </div>
      <span className="font-black text-[11px] uppercase tracking-[0.2em]">Marcus.7729</span>
    </button>
  </header>

  <main ref={scrollRef} onScroll={handleScroll} className="flex-1 flex overflow-x-auto snap-x snap-mandatory no-scrollbar">

    {/* SCHEDULE SECTION */}
    <section className="min-w-full h-full snap-start px-10 pt-10">
      <div className="mb-8">
        <h2 className="text-3xl font-black italic text-[#47510B] uppercase tracking-tighter">
          Todays Schedule<span className="text-[#CAD23C]">.</span>
        </h2>
      </div>
      <ScheduleTab onViewReport={handleOpenReport} />
    </section>

    {/* REPORTS SECTION */}
    <section className="min-w-full h-full snap-start px-10 pt-10">
      <div className="mb-8">
        <h2 className="text-3xl font-black italic text-[#47510B] uppercase tracking-tighter">
          Issues<span className="text-[#CAD23C]">.</span>
        </h2>
      </div>
      <ReportsTab onSelectReport={setSelectedReport} />
    </section>

    {/* TRAINING SECTION */}
    <section className="min-w-full h-full snap-start px-10 pt-10">
      <div className="mb-8">
        <h2 className="text-3xl font-black italic text-[#47510B] uppercase tracking-tighter">
          Learn<span className="text-[#CAD23C]">.</span>
        </h2>
      </div>
      <TrainingTab />
    </section>

  </main>

  {/* FOOTER - Remains fixed at bottom */}
  <footer className="fixed bottom-12 left-1/2 -translate-x-1/2 z-50">
    <nav className="bg-[#47510B]/90 backdrop-blur-3xl border border-white/20 px-4 py-3.5 rounded-[40px] shadow-2xl flex items-center gap-3">
      {tabs.map((tab) => (
        <button key={tab.id} onClick={() => scrollToTab(tab.id)} className={`flex items-center gap-3 px-8 py-4 rounded-[30px] transition-all duration-500 group ${activeTab === tab.id ? "bg-[#CAD23C] shadow-xl scale-110" : "text-white/40 hover:text-white"}`}>
          <div style={{ color: activeTab === tab.id ? '#47510B' : 'inherit' }}>{tab.icon}</div>
          {activeTab === tab.id && <span className="text-[11px] font-[1000] uppercase tracking-widest text-[#47510B]">{tab.label}</span>}
        </button>
      ))}
    </nav>
  </footer>
</div>
    </div>
  );
};

export default WorkerDashboard;
